from pathlib import Path
import json,base64,html,shutil,zipfile
P=Path(__file__).resolve().parent;R=P.parents[2];G=P/'generated';L=R/'research/ontology-adaptation/template-library';K=R/'.agents/skills/technical-video-explainer'
manifest=json.loads((G/'manifest.json').read_text());catalog=json.loads((L/'catalog.json').read_text())
# Source / reconstruction observations are explicit human-readable comparisons, not a pixel-similarity score.
findings=[
('The source changes from speaker to white stage, then grows the card.','Opening card growth was retimed after inspecting 39.2–41.5s source samples; presenter remains a static placeholder.','Transition timing is still approximate; the card mark, font and caption grouping differ.','Establish the stage before introducing the referent. Align visible events from frames, not just the product-name timestamp.'),
('One named product and a short audience subtitle establish the role.','The generated scene uses the same single-card hierarchy.','The subtitle is present on the card rather than following a separately certified source reveal; typography remains approximate.','Definition needs one stable referent and one meaningful qualifier, not an early architecture diagram.'),
('The source shrinks the card and adds database/tool symbols with bidirectional arrowheads.','The revised scene retains the product, restores the tool glyph and adds arrowheads at both ends of the source-style connections.','Generic database/tool silhouettes and exact endpoint positions still differ. Proposed Data/Tools text labels are not shown in the reference-style render.','Connection, flow and dependency are different meanings. Record connector semantics and flag plan/render label omissions.'),
('The source replaces the diagram with a large illustrative chat and returned product totals.','The revised chat preserves the question and illustration values; results reach readable opacity sooner, and the action is revealed without moving its baseline.','Query typing, answer reveal timing, bubbles and glyphs are approximate; results can still be entering at the end of this short beat.','When a capability needs proof by example, preserve the same question, evidence and output rather than generic answer boxes.'),
('An action suggestion appears under the retained answer.','The generated action stays attached to the product totals.','The source action reveal and caption phrase timing are not frame-exact; no actual campaign execution is depicted.','Show action status explicitly. A suggestion, request, confirmation and completed operation are distinct visual states.'),
('The same chat shrinks into a green governance enclosure with a shield.','The generated enclosure retains the chat and now uses a sourced shield-lock icon.','Boundary position/radius, shield design and exact shrink/draw timing differ; this is a shorthand for governance.','Add a constraint to the mechanism already understood. Use a separate permission example if the access model itself is the lesson.'),
('The known product tilts, layers extrude, then the graphic holds.','The revised scene uses explicit SVG plane matrices: a 110px flat card tilts, five backplates expand, then the front card separates from the stationary stack.','Geometry is estimated from decoded source samples. Texture, tiny spacing and exact source easing remain approximate; text no longer animates its font size during the tilt.','Treat plane change, extrusion and hold as distinct states. Check readability after transforms, not only in flat assets.'),
('A curved annotation identifies the business audience above the central card.','The generated label anchors to the known product without replacing the family.','Leader shape, endpoint and label spacing differ from source.','Annotate the comparison criterion before introducing the contrasting role. A leader is not a data-flow arrow.'),
('Genie Code appears left of the central Genie One card with a technical-work note below.','The revised peer cards emerge from beneath the front card, with fixed serif text metrics and darker role labels. Their hierarchy follows the source.','Card shapes, overlap and source font are approximate; no notebook demo is inserted into this family beat.','Use position for sibling status and text for role differences. Equal category is not delegation or ownership.'),
('Genie Agents completes the family on the right, with both audiences identified.','The generated third card preserves the central anchor and left/right role arrangement.','Card subtitle wrapping, exact reveal and perspective are approximate.','Distinguish shared audience from specialist function; do not invent call routes among peer products.'),
('The third product receives a curved domain-specific-work annotation.','The generated annotation adds the specialist role while retaining all products.','The revised annotation stays on one line as in the source. Its exact position, curve and reveal remain approximate.','The role should be named. A robot or brain would add imagery without explaining the domain constraint.'),
('The source cuts back to the speaker rather than introducing another concept.','The generated scene uses the requested full-frame static fictional presenter.','Person, background and natural movement intentionally differ; cut/caption timing is approximate.','A no-new-graphic beat is part of the template library. Do not force a diagram onto conversational handoffs.')]
for s,f in zip(manifest['scenes'],findings):s['comparison']={'source_behavior':f[0],'generated_behavior':f[1],'remaining_difference':f[2],'transfer_rule':f[3],'verdict':'structural draft; fidelity review pending','basis':'Matched source/generated start, middle and end frames; additional source tilt samples and 6fps caption observations used for this revision; no numeric fidelity score'}
(G/'manifest.json').write_text(json.dumps(manifest,indent=2))
# Keep the actual visual reference inside the skill package, so it is more than instructions without examples.
(K/'references/evidence').mkdir(exist_ok=True);(K/'references/reconstructions').mkdir(exist_ok=True)
for s in catalog['sequences']:
 shutil.copy(R/'research/ontology-adaptation/graphics-study'/s['sheet'],K/'references/evidence'/s['sheet']);s['reference_sheet']='evidence/'+s['sheet'];s['evidence_frames_location']='Full PNG samples remain in the ReelFactory project graphics-study directory; the portable sheet contains all eight sampled frames.'
(K/'references/catalog.json').write_text(json.dumps(catalog,indent=2))
for s in manifest['scenes']:shutil.copy(G/s['folder']/'comparison-end.jpg',K/'references/reconstructions'/('scene-'+s['id']+'.jpg'))
q={'mode':'reference-reconstruction','audience':'Technical practitioners; reference wording retained to study the visual grammar','scope':manifest['coverage'],'generation_authorization':'Latest user request explicitly asks to generate all current storyboard graphics and compare them with the original; final fidelity approval remains pending.','technical_rewrite':None,'scenes':manifest['scenes']}
for s in q['scenes']:s['status']='rendered_for_review';s['generation_authorized_by_user']=True
(K/'references/example-storyboard.json').write_text(json.dumps(q,indent=2))
md='# All storyboard graphics — comparison and reusable rules\n\n**Coverage:** all 12 scenes of the current 46-second storyboard. The full reference is catalogued in 27 source sequences; the other source sequences have not been newly reconstructed in this pass.\n\nA fresh render reuses and adjusts the editable V1/GSAP reconstruction. This is not a Remotion migration or pixel-exact recreation. Static fictional presenter images are intentional placeholders. The source sample numbers and chat are illustrative.\n\n'
for s in manifest['scenes']:
 f=s['comparison'];md+=f'## Scene {s["id"]} — {s["template_variant"]}\n\n**Spoken excerpt:** {s["transcript"]}\n\n**Teaching purpose:** {s["intended_understanding"]}\n\n**Why selected:** {s["reason"]}\n\n**Better alternative / tradeoff:** {s["alternative_and_tradeoff"]}\n\n**Original:** {f["source_behavior"]}\n\n**Generated:** {f["generated_behavior"]}\n\n**Remaining difference:** {f["remaining_difference"]}\n\n**Reusable rule:** {f["transfer_rule"]}\n\n[Three-state comparison and motion](generated/{s["folder"]}/comparison.mp4) · [Graphic keyframe](generated/{s["folder"]}/graphic.png)\n\n'
(P/'COMPARISON-AND-RULES.md').write_text(md)
import re
portable=re.sub(r'\[Three-state comparison and motion\]\(generated/scene-(\d+)/comparison.mp4\) · \[Graphic keyframe\]\(generated/scene-\d+/graphic.png\)',lambda m:'[Matched end-state comparison](reconstructions/scene-'+m[1]+'.jpg). Full motion and isolated keyframes are in the ReelFactory project.',md)
(K/'references/comparison-findings.md').write_text(portable)
def uri(path):
 ext=path.suffix;mime={'.jpg':'image/jpeg','.png':'image/png','.mp4':'video/mp4'}[ext];return 'data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()
scenes=[]
for s in manifest['scenes']:
 obj=dict(s);obj['frames']={phase:uri(G/s['folder']/f'comparison-{phase}.jpg') for phase in ['start','middle','end']};obj['clip']=uri(G/s['folder']/'comparison.mp4');scenes.append(obj)
nav=''.join(f'<button data-scene="{i}">{s["id"]} · {html.escape(s["template_variant"])}</button>' for i,s in enumerate(scenes))
sourcecards=''
for s in catalog['sequences']:
 sourcecards+=f'<details class="source-recipe"><summary>{s["id"]} · {html.escape(s["template_id"])}</summary><img loading="lazy" alt="Eight original source frames" src="{uri(R/"research/ontology-adaptation/graphics-study"/s["sheet"])}"><p><b>Teaches:</b> {html.escape(s["teaching_purpose"])}</p><p><b>Structure:</b> {html.escape(s["observed_state_pattern"])}</p><p><b>Keep:</b> {html.escape(s["persistent_context"])}</p><p><b>Choose when:</b> {html.escape(s["selection_rule"])}</p><p><b>Alternative:</b> {html.escape(s["alternative_rule"])}</p><p><b>Avoid:</b> {html.escape(s["misuse_to_avoid"])}</p><details><summary>Approximate transcript excerpt</summary><p>{html.escape(s["transcript_excerpt"])}</p></details></details>'
page='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Technical explainer · template learning review</title><style>*{box-sizing:border-box}body{margin:0;background:#10191f;color:#eaf1f4;font:16px/1.55 system-ui}main{max-width:1450px;margin:auto;padding:30px}h1{font-size:36px;line-height:1.15;max-width:1050px}h2{font-size:25px;margin-top:32px}p{color:#c2d2d9;max-width:1120px}small{color:#ecbf7b}video,img{width:100%;display:block;background:#172129;border-radius:8px}nav,.controls{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}button,select{font:inherit;background:#1d3540;border:1px solid #597782;color:#fff;padding:9px 13px;border-radius:7px;cursor:pointer}button.active{border-color:#ecc185;background:#57442b}.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.panel{padding:20px;background:#192e37;border:1px solid #35505b;border-radius:10px}.panel h3{font-size:16px;margin:14px 0 4px;color:#edc184}.panel p{margin:0 0 10px;font-size:15px}blockquote{margin:18px 0;padding:14px 20px;border-left:3px solid #80c8bd;color:#fff}.source-recipe{background:#192e37;border:1px solid #35505b;border-radius:10px;padding:16px;margin:12px 0}.source-recipe img{margin-top:18px}.source-recipe summary{cursor:pointer;font-weight:650}.note{font-size:13px}a{color:#a9ded6}#clock{font-variant-numeric:tabular-nums}@media(max-width:800px){main{padding:16px}.columns{grid-template-columns:1fr}h1{font-size:28px}}</style><main><small>REELFACTORY / REFERENCE → RULES → NEW CONTENT</small><h1>What the graphic teaches, why it fits, and how to reuse it</h1><p>27 original source sequences labelled. All 12 scenes of the current 46-second storyboard rendered. Each scene includes matched source/generated frames, motion, rationale, an alternative and a transfer rule.</p><p class="note">Scope: the 12 generated scenes cover source 00:37.33–01:23.70. The other full-video sequences are catalogued reference evidence, not newly generated replicas. This study uses V1/GSAP, not Remotion. Static fictional presenters are placeholders. Teaching intent is interpreted; sampled frames do not establish pixel-exact timing.</p><h2>Full synchronized comparison</h2><video id="full" controls playsinline preload="metadata" src="'''+uri(G/'comparison.mp4')+'''"></video><div class="controls"><button id="compare-version">Show previous generated version</button><span id="version-label">Original left · refined right</span></div><h2>Review all storyboard graphics</h2><nav>'''+nav+'''</nav><small id="type"></small><h2 id="title"></h2><blockquote id="quote"></blockquote><img id="frame" alt="Original left; generated right at the same source time"><div class="controls"><button data-phase="start">Start</button><button data-phase="middle">Middle</button><button data-phase="end">End</button><span id="clock"></span></div><div class="columns"><div class="panel"><h3>What this must teach</h3><p id="goal"></p><h3>Why this graphic</h3><p id="why"></p><h3>Alternative and tradeoff</h3><p id="alternative"></p><h3>How it changes</h3><p id="motion"></p><h3>What can change for a new script</h3><p>Product names, audience labels, question, evidence, action and domain. Preserve the relationship only when it remains true.</p></div><div class="panel"><h3>Original behavior</h3><p id="source"></p><h3>Generated behavior</h3><p id="generated"></p><h3>Remaining differences</h3><p id="difference"></p><h3>Rule for future content</h3><p id="rule"></p><h3>Check the scene motion</h3><video id="scene-video" controls playsinline preload="metadata"></video><div class="controls"><button id="minus">−1 frame</button><button id="plus">+1 frame</button><select id="speed"><option value=".25">0.25×</option><option value=".5">0.5×</option><option value="1" selected>1×</option></select></div></div></div><h2 id="source-library">Original-video pattern library</h2><p>These are source samples, not generated graphics. Each recipe records observed structure, interpreted teaching purpose, continuity, selection conditions and misuse risks. Open any sequence to inspect its evidence.</p>'''+sourcecards+'''<h2>Skill workflow</h2><p>Research the subject → rewrite for the technical audience → label teaching beats → select and justify a template → human storyboard review → generate approved assets/keyframes → animate → compare → update the rules.</p><p class="note">The local skill includes instructions, a 27-sequence reference catalog, visual evidence, this 12-scene worked example, a technical rewrite example and a plan validator. It guides the agent; it is not a trained model or an automatic arbitrary-script video compiler.</p></main><script>const scenes='''+json.dumps(scenes).replace('</','<' + chr(92) + '/')+''';let selected=0,phase='end';const el=id=>document.getElementById(id);function show(i){selected=i;const s=scenes[i],c=s.comparison;el('type').textContent=s.template_id+' / '+s.template_variant;el('title').textContent='Scene '+s.id+' · '+s.visual_type;el('quote').textContent=s.transcript;for(const[k,v]of Object.entries({goal:s.intended_understanding,why:s.reason,alternative:s.alternative_and_tradeoff,motion:s.state_plan,source:c.source_behavior,generated:c.generated_behavior,difference:c.remaining_difference,rule:c.transfer_rule}))el(k).textContent=v;el('scene-video').src=s.clip;document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',+b.dataset.scene===i));showPhase(phase)}function showPhase(p){phase=p;const s=scenes[selected];el('frame').src=s.frames[p];el('clock').textContent=p+' · source '+s.sample_source_times[p].toFixed(3)+'s';document.querySelectorAll('[data-phase]').forEach(b=>b.classList.toggle('active',b.dataset.phase===p))}document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>show(+b.dataset.scene));document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>showPhase(b.dataset.phase));const v=el('scene-video');el('minus').onclick=()=>{v.pause();v.currentTime=Math.max(0,v.currentTime-1/30)};el('plus').onclick=()=>{v.pause();v.currentTime=Math.min(v.duration,v.currentTime+1/30)};el('speed').onchange=e=>v.playbackRate=+e.target.value;const fullPlayer=el('full'),refinedSource=fullPlayer.src,previousSource='''+json.dumps(uri(P/'previous-graphics/comparison.mp4'))+''';let previous=false;el('compare-version').onclick=()=>{const t=fullPlayer.currentTime,paused=fullPlayer.paused;previous=!previous;fullPlayer.src=previous?previousSource:refinedSource;fullPlayer.addEventListener('loadedmetadata',()=>{fullPlayer.currentTime=t;if(!paused)fullPlayer.play()},{once:true});el('compare-version').textContent=previous?'Show refined generated version':'Show previous generated version';el('version-label').textContent=previous?'Original left · previous right':'Original left · refined right'};show(0);</script>'''
(P/'template-review.html').write_text(page)
(P/'refined-review.html').write_text(page)
# A portable local skill package; source footage itself is not included.
with zipfile.ZipFile(P/'technical-video-explainer-skill.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in K.rglob('*'):
  if f.is_file():z.write(f,Path('technical-video-explainer')/f.relative_to(K))
